{
  "description": "The creature is a chimeric animal shown in right-facing profile standing on a small patch of ground. It has the overall body shape, fur, head, hind legs and long bushy tail of a red fox, but with large feathered wings and a feathered chest patch in place of forelimbs. The fur is reddish-orange on the head, neck, back, sides and tail with white on the muzzle, throat, chest and belly and darker brown-black on the lower hind legs. The two wings are folded against the sides of the body and show the mottled tan, cream, grey and brown patterning with dark spots and bars typical of a barn owl. The animal stands upright on its hind legs with its tail extending behind it along the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "narrow fox head with pointed muzzle, black nose, amber eye, white fur on muzzle, chin and throat and reddish-orange fur on top and sides",
      "where": "at the top front of the body, facing to the right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two upright pointed triangular ears with reddish outer fur, black on the back edges and pale cream-white inner fur",
      "where": "on top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short reddish-brown fur fading to white on the inner thigh and belly and to dark brown-black on the lower shin",
      "where": "under the rear half of the body, supporting the body in a bipedal stance"
    },
    {
      "part": "feet",
      "looks_like": "two dark-furred hind paws with visible black claws and textured pads",
      "where": "at the bottom of the hind legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long thick bushy tail covered in long reddish-orange fur with a white tip at the end",
      "where": "extending from the rear of the body behind the hind legs, lying along the ground to the right"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered flight feathers, cream and pale grey undersides with dark brown-black bars and spots, and mottled tan, grey and brown upper coverts with white and black speckles",
      "where": "attached at the shoulder on each side of the torso, folded against the body, one prominently visible on the near side and one partially visible on the far side"
    },
    {
      "part": "feathers",
      "looks_like": "soft overlapping owl-like feathers, cream with small dark brown spots on the chest bib and mottled tan, grey and white with dark speckling on the wing coverts and flight feathers",
      "where": "covering both wings and forming a bib across the front of the chest and lower throat"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
